import random

class MusicPlayer:
    VOLUME_MIN = 0
    VOLUME_MAX = 100
    DEFAULT_VOLUME = 50

    def __init__(self):
        self._playlist = []
        self._current_song = None
        self._volume = self.DEFAULT_VOLUME

    @property
    def playlist(self):
        return self._playlist.copy()

    def add_song(self, song):
        self._playlist.append(song)

    def remove_song(self, song):
        if song in self._playlist:
            self._playlist.remove(song)
            if self._current_song == song:
                self.stop()

    def play(self):
        if self._playlist and self._current_song:
            return self._playlist[0]
        elif len(self._playlist):
            return False

    def stop(self):
        if self._current_song:
            self._current_song = None
            return True
        else:
            return False

    def switch_song(self):
        if self._current_song:
            current_index = self._get_current_index()
            if current_index < len(self._playlist) - 1:
                self._current_song = self._playlist[current_index + 1]
                return True
            else:
                return False
        else:
            return False

    def previous_song(self):
        if self._current_song:
            current_index = self._get_current_index()
            if current_index > 0:
                self._current_song = self._playlist[current_index - 1]
                return True
            else:
                return False
        else:
            return False

    def set_volume(self, volume):
        if self.VOLUME_MIN <= volume <= self.VOLUME_MAX:
            self._volume = volume
        else:
            return False

    def shuffle(self):
        if self._playlist:
            random.shuffle(self._playlist)
            return True
        else:
            return False

    def _get_current_index(self):
        return self._playlist.index(self._current_song)
